vulnerabilities.suggested_fix_code:
function checkEligibility() {
  const name = document.getElementById('voterName').value.trim();
  const age  = parseInt(document.getElementById('voterAge').value);
  const vid  = document.getElementById('voterID').value.trim();
  if (!name || isNaN(age) || !vid) { return; } // Added isNaN check for age
  if (age >= 18) { // Corrected the condition to check for eligibility (age 18 or above)
    currentVoter = name;
    showResult('Eligible to vote!', 'success');
    openVotingPanel();
  } else { // If age is less than 18, they are not eligible
    showResult('Not Eligible. Voter must be above 18 years.', 'error');
  }
}

